=== Explosion
public class Explosion : MonoBehaviour
{
	private static GameObject prefab;
	private DustEmitter dustEmitter;
	private Animator anim;
	private Light light;
	private float explosionScale;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/Explosion.prefab"));
	private void Awake()
	{
		explosionScale = 1f;
		dustEmitter = Globals.ChaosInst<DustEmitter>(DustEmitter.Prefab, transform, transform.position);
		anim = GetComponent<Animator>();
		light = transform.Find("ExplosionLight").GetComponent<Light>();
	}
	public void Explode(float newExplosionScale = 1f)
	{
		explosionScale = newExplosionScale;
		transform.localScale *= explosionScale;
		dustEmitter.EmitCircle(100, explosionScale, 22f, 1.2f);
		anim.Play("Explosion");
	}
	public void LateUpdate()
	{
		if (explosionScale != 1f)
		{
			light.intensity *= explosionScale;
		}
	}
}
=== FireBomb
public class FireBomb : MonoBehaviour
{
	private bool markedForDestroy;
	private static GameObject _prefab;
	public Attack attack;
	public FollowTransform followTransform;
	public Animator anim;
	private ChaosQuickStopwatch fuseTimer;
	public float fuseTime = 0.75f;
	public Transform targetTrans;
	public Entity targetEntity;
	public bool fastAnimPlayed;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Effects/Fire/FireBomb.prefab");
			}
			return _prefab;
		}
	}
	private void Start()
	{
		anim.Play("Idle");
		fuseTimer = new ChaosQuickStopwatch(fuseTime);
		fuseTimer.IsRunning = true;
		if (targetTrans != null)
		{
			followTransform.followTransform = targetTrans;
		}
	}
	private void FixedUpdate()
	{
		if (markedForDestroy)
		{
			Object.Destroy(gameObject);
			return;
		}
		if (targetEntity == null || targetEntity.fsm.currentStateName.Contains("Dead"))
		{
			markedForDestroy = true;
			return;
		}
		if (fuseTimer.IsRunning)
		{
			if (!fastAnimPlayed && fuseTimer.TimePercentage >= 0.7f)
			{
				fastAnimPlayed = true;
				anim.Play("IdleFast");
			}
			return;
		}
		markedForDestroy = true;
		if (targetTrans != null)
		{
			attack.EnableForOneFrame();
			FireExplosion.SpawnExplosion(transform.position, 0.25f, 0.5f);
			SoundManager.PlayAudioWithDistance("ImpactFire", transform.position, null, 24f, -1f, 1.2f);
		}
	}
	public static void SpawnFireBomb(Vector3 spawnPos, string skillCategory, string skillID, Entity entity = null, float fuseTime = 1f, bool isEmpowered = false, Vector3? knockbackOverwriteVector = null)
	{
		if (!(entity == null))
		{
			FireBomb fireBomb = Globals.ChaosInst<FireBomb>(Prefab, null, spawnPos);
			fireBomb.targetTrans = entity.hurtBoxTransform;
			fireBomb.followTransform.followOffset = Vector3.up * 0.25f;
			if (entity is MovingStatue)
			{
				fireBomb.followTransform.followOffset = Vector3.up * 0.5f;
			}
			fireBomb.attack.SetAttackInfo(skillCategory, skillID, (!isEmpowered) ? 2 : 3);
			if (knockbackOverwriteVector.HasValue)
			{
				fireBomb.attack.knockbackOverwriteVector = knockbackOverwriteVector.Value;
			}
			fireBomb.fuseTime = fuseTime;
			fireBomb.targetEntity = entity;
		}
	}
}
=== FrostField
public class FrostField : MonoBehaviour
{
	private static GameObject _prefab;
	public string skillCategory = string.Empty;
	public string skillID = string.Empty;
	public int skillLevel;
	private float radius;
	public float freezeDelay;
	public float freezeChance;
	public float pvpFreezeChance = 0.08f;
	[HideInInspector]
	public int freezeDelayStopwatchID = -1;
	[HideInInspector]
	public Entity parentEntity;
	[HideInInspector]
	public Health parentHealth;
	private List<GameObject> validTargets;
	[HideInInspector]
	public List<GameObject> doNotTargetList;
	public GameObject currentFreeze;
	private int targetIndex;
	private Attack atkBox;
	private bool atkBoxDisableQueued;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FrostField.prefab");
			}
			return _prefab;
		}
	}
	private void Awake()
	{
		radius = transform.Find("Sprite").GetComponent<SpriteRenderer>().sprite.bounds.max.x;
		radius *= transform.localScale.x;
		if (radius < 0f)
		{
			radius *= -1f;
		}
	}
	private void Start()
	{
		atkBox = Globals.ChaosInst<Attack>(Attack.CirclePrefab, transform);
		atkBox.collider.transform.localScale = new Vector3(0.25f, 0.25f, 1f);
		atkBox.SetAttackInfo(skillCategory, skillID, skillLevel);
		atkBox.collider.enabled = false;
	}
	private void FixedUpdate()
	{
		if (atkBox.collider.enabled)
		{
			if (!atkBoxDisableQueued)
			{
				atkBoxDisableQueued = true;
				return;
			}
			atkBoxDisableQueued = false;
			atkBox.collider.enabled = false;
		}
	}
	private void Update()
	{
		if (parentEntity == null || (parentHealth != null && parentHealth.healthStat.CurrentValue <= 0f) || parentEntity.fsm.currentStateName.Contains("Dead") || parentEntity.fsm.currentStateName.Contains("Paused") || !ChaosSt
		{
			return;
		}
		freezeDelayStopwatchID = ChaosStopwatch.Begin(freezeDelay * Random.Range(0.8f, 1.2f));
		validTargets = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, radius, playerTagOnly: false, doNotTargetList, parentEntity.gameObject);
		if (validTargets.Count == 0)
		{
			return;
		}
		if (GameController.pvpOn)
		{
			if (Random.value > pvpFreezeChance)
			{
				return;
			}
		}
		else if (Random.value > freezeChance)
		{
			return;
		}
		targetIndex = Random.Range(0, validTargets.Count);
		FreezeLocation(validTargets[targetIndex].transform.position);
		validTargets.Clear();
	}
	public void FreezeLocation(Vector2 targetLoc)
	{
		atkBox.transform.position = targetLoc;
		atkBox.collider.enabled = true;
	}
}
